mapper.sql:
(
( ( #{scope.scopeType} = 'COMPANY' AND #{scope.companyId} = candidate_employee.company_id ) OR ( #{scope.scopeType} = 'SELF' AND #{scope.principalEmployeeId} = candidate_employee.employee_id ) OR ( #{scope.scopeType} = 'ORGANIZATION' AND EXISTS ( SELECT 1 FROM employment_assignment current_assignment JOIN organization_identity current_assignment_organization ON current_assignment_organization.organization_id = current_assignment.organization_id AND current_assignment_organization.company_id = candidate_employee.company_id AND current_assignment_organization.identity_status = 'ACTIVE' JOIN organization_current_projection current_assignment_projection ON current_assignment_projection.organization_id = current_assignment_organization.organization_id JOIN organization_version current_assignment_version ON current_assignment_version.organization_version_id = current_assignment_projection.current_version_id AND current_assignment_version.organization_id = current_assignment_organization.organization_id AND current_assignment_version.status = 'ACTIVE' AND current_assignment_version.effective_from <= #{authorizationTime} AND ( current_assignment_version.effective_to IS NULL OR current_assignment_version.effective_to > #{authorizationTime} ) WHERE current_assignment.employee_id = candidate_employee.employee_id AND current_assignment.record_status = 'ACTIVE' AND current_assignment.version_valid_to IS NULL AND current_assignment.effective_from <= #{authorizationTime} AND ( current_assignment.effective_to IS NULL OR current_assignment.effective_to > #{authorizationTime} ) AND ( ( #{scope.includeDescendants} = FALSE AND #{scope.organizationId} = current_assignment.organization_id ) OR ( #{scope.includeDescendants} = TRUE AND EXISTS ( SELECT 1 FROM organization_current_closure closure WHERE closure.ancestor_organization_id = #{scope.organizationId} AND closure.descendant_organization_id = current_assignment.organization_id ) ) ) ) ) )
)

(
( ( #{scope.scopeType} = 'COMPANY' AND #{scope.companyId} = candidate_employee.company_id ) OR ( #{scope.scopeType} = 'SELF' AND #{scope.principalEmployeeId} = candidate_employee.employee_id ) OR ( #{scope.scopeType} = 'ORGANIZATION' AND EXISTS ( SELECT 1 FROM employment_assignment current_assignment JOIN organization_identity current_assignment_organization ON current_assignment_organization.organization_id = current_assignment.organization_id AND current_assignment_organization.company_id = candidate_employee.company_id AND current_assignment_organization.identity_status = 'ACTIVE' JOIN organization_current_projection current_assignment_projection ON current_assignment_projection.organization_id = current_assignment_organization.organization_id JOIN organization_version current_assignment_version ON current_assignment_version.organization_version_id = current_assignment_projection.current_version_id AND current_assignment_version.organization_id = current_assignment_organization.organization_id AND current_assignment_version.status = 'ACTIVE' AND current_assignment_version.effective_from <= #{authorizationTime} AND ( current_assignment_version.effective_to IS NULL OR current_assignment_version.effective_to > #{authorizationTime} ) WHERE current_assignment.employee_id = candidate_employee.employee_id AND current_assignment.record_status = 'ACTIVE' AND current_assignment.version_valid_to IS NULL AND current_assignment.effective_from <= #{authorizationTime} AND ( current_assignment.effective_to IS NULL OR current_assignment.effective_to > #{authorizationTime} ) AND ( ( #{scope.includeDescendants} = FALSE AND #{scope.organizationId} = current_assignment.organization_id ) OR ( #{scope.includeDescendants} = TRUE AND EXISTS ( SELECT 1 FROM organization_current_closure closure WHERE closure.ancestor_organization_id = #{scope.organizationId} AND closure.descendant_organization_id = current_assignment.organization_id ) ) ) ) ) )
)

(
( ( #{scope.scopeType} = 'COMPANY' AND #{scope.companyId} = fact.company_id ) OR ( #{scope.scopeType} = 'SELF' AND #{scope.principalEmployeeId} = fact.employee_id ) OR ( #{scope.scopeType} = 'ORGANIZATION' AND EXISTS ( SELECT 1 FROM employment_assignment current_assignment JOIN organization_identity current_assignment_organization ON current_assignment_organization.organization_id = current_assignment.organization_id AND current_assignment_organization.company_id = fact.company_id AND current_assignment_organization.identity_status = 'ACTIVE' JOIN organization_current_projection current_assignment_projection ON current_assignment_projection.organization_id = current_assignment_organization.organization_id JOIN organization_version current_assignment_version ON current_assignment_version.organization_version_id = current_assignment_projection.current_version_id AND current_assignment_version.organization_id = current_assignment_organization.organization_id AND current_assignment_version.status = 'ACTIVE' AND current_assignment_version.effective_from <= #{authorizationTime} AND ( current_assignment_version.effective_to IS NULL OR current_assignment_version.effective_to > #{authorizationTime} ) WHERE current_assignment.employee_id = fact.employee_id AND current_assignment.record_status = 'ACTIVE' AND current_assignment.version_valid_to IS NULL AND current_assignment.effective_from <= #{authorizationTime} AND ( current_assignment.effective_to IS NULL OR current_assignment.effective_to > #{authorizationTime} ) AND ( ( #{scope.includeDescendants} = FALSE AND #{scope.organizationId} = current_assignment.organization_id ) OR ( #{scope.includeDescendants} = TRUE AND EXISTS ( SELECT 1 FROM organization_current_closure closure WHERE closure.ancestor_organization_id = #{scope.organizationId} AND closure.descendant_organization_id = current_assignment.organization_id ) ) ) ) ) )
)

mapper.select:
SELECT DISTINCT candidate_organization.organization_id FROM company target_company JOIN organization_identity candidate_organization ON candidate_organization.company_id = target_company.company_id AND candidate_organization.identity_status = 'ACTIVE' JOIN organization_current_projection candidate_projection ON candidate_projection.organization_id = candidate_organization.organization_id JOIN organization_version candidate_version ON candidate_version.organization_version_id = candidate_projection.current_version_id AND candidate_version.organization_id = candidate_organization.organization_id AND candidate_version.status = 'ACTIVE' AND candidate_version.effective_from <= #{authorizationTime} AND ( candidate_version.effective_to IS NULL OR candidate_version.effective_to > #{authorizationTime} ) WHERE target_company.company_id = #{companyId} AND target_company.status = 'ACTIVE' AND (
( ( #{scope.scopeType} = 'COMPANY' AND #{scope.companyId} = target_company.company_id ) OR ( #{scope.scopeType} = 'ORGANIZATION' AND EXISTS ( SELECT 1 FROM organization_identity scoped_organization JOIN organization_current_projection scoped_projection ON scoped_projection.organization_id = scoped_organization.organization_id JOIN organization_version scoped_version ON scoped_version.organization_version_id = scoped_projection.current_version_id AND scoped_version.organization_id = scoped_organization.organization_id AND scoped_version.status = 'ACTIVE' AND scoped_version.effective_from <= #{authorizationTime} AND ( scoped_version.effective_to IS NULL OR scoped_version.effective_to > #{authorizationTime} ) WHERE scoped_organization.organization_id = #{scope.organizationId} AND scoped_organization.company_id = target_company.company_id AND scoped_organization.identity_status = 'ACTIVE' ) AND ( #{scope.organizationId} = candidate_organization.organization_id OR ( #{scope.includeDescendants} = TRUE AND EXISTS ( SELECT 1 FROM organization_current_closure closure WHERE closure.ancestor_organization_id = #{scope.organizationId} AND closure.descendant_organization_id = candidate_organization.organization_id ) ) ) ) OR ( #{scope.scopeType} = 'SELF' AND EXISTS ( SELECT 1 FROM employee principal_employee JOIN employment_assignment current_assignment ON current_assignment.employee_id = principal_employee.employee_id AND current_assignment.organization_id = candidate_organization.organization_id AND current_assignment.record_status = 'ACTIVE' AND current_assignment.version_valid_to IS NULL AND current_assignment.effective_from <= #{authorizationTime} AND ( current_assignment.effective_to IS NULL OR current_assignment.effective_to > #{authorizationTime} ) WHERE principal_employee.employee_id = #{scope.principalEmployeeId} AND principal_employee.company_id = target_company.company_id ) ) )
) ORDER BY candidate_organization.organization_id
